def split_qkv(
  source: torch.Tensor,
) -&gt; tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
  if source.shape[0] % 3 == 0:
    return torch.chunk(source, 3, dim=0)
  if source.shape[1] % 3 == 0:
    return torch.chunk(source, 3, dim=1)
  raise ValueError(&#039;cannot split qkv: tensor shape not divisible by three&#039;)


def slice_value_head(
  mat: torch.Tensor, head: int, num_heads: int
) -&gt; torch.Tensor:
  rows, cols = mat.shape
  if rows % num_heads == 0:
    span = rows // num_heads
    start = head * span
    return mat[start : start + span, :]
  if cols % num_heads == 0:
    span = cols // num_heads
    start = head * span
    return mat[:, start : start + span].T
  raise ValueError(
    &#039;value projection shape is incompatible with the requested head count&#039;
  )


