def find_key_for_component(
  state: dict[str, Any], layer: int, patterns: list[str]
) -&gt; str | None:
  lowered_items = [
    (key, key.lower()) for key in state.keys() if matches_layer(key, layer)
  ]
  # prefer exact suffix matches
  for pattern in patterns:
    for key, low in lowered_items:
      if low.endswith(pattern):
        return key
  # fallback to substring matches
  for pattern in patterns:
    for key, low in lowered_items:
      if pattern in low:
        return key
  return None


